begin;
create extension if not exists pgtap with schema extensions;
select plan(15);
select is((select jsonb_array_length(metadata->'features') from plans where plan_key='free'),4,'fresh stack includes free catalog features');
select is((select count(*)::int from plan_entitlements e join plans p on p.id=e.plan_id where p.plan_key='membership_preview'),(select count(*)::int from entitlement_definitions),'preview plan resolves configured definitions after fresh seed');
insert into auth.users(id,email) values('f0000000-0000-4000-8000-000000000001','product-one@example.test'),('f0000000-0000-4000-8000-000000000002','product-two@example.test');
insert into learner_ability_estimates(user_id,dimension,estimate_level,confidence_level) values('f0000000-0000-4000-8000-000000000001','listening',3,2);
insert into method_effectiveness(user_id,teaching_method,target_skill) values('f0000000-0000-4000-8000-000000000001','conversation','spoken_expression');
create temp table settings_payload as select '{"nativeLanguage":"zh","interfaceLanguage":"es","goals":[{"key":"work","priority":5},{"key":"daily_communication","priority":2}],"methods":{"conversation":-2,"role_play":0,"listening":1,"speaking":0,"sentence_building":0,"vocabulary_context":0,"grammar_explanation":0,"guided_writing":0,"review":0,"transfer":0},"correction":"minimal","pace":"brisk"}'::jsonb data;
select lives_ok($$select save_product_settings('f0000000-0000-4000-8000-000000000001',(select data from settings_payload))$$,'valid preferences saved atomically');
select is((select native_language from profiles where user_id='f0000000-0000-4000-8000-000000000001'),'zh','support language saved');
select is((select interface_language from profiles where user_id='f0000000-0000-4000-8000-000000000001'),'es','interface language saved');
select is((select estimate_level::int from learner_ability_estimates where user_id='f0000000-0000-4000-8000-000000000001'),3,'settings do not rewrite measured ability');
select is((select confidence_level::int from method_effectiveness where user_id='f0000000-0000-4000-8000-000000000001'),0,'settings do not rewrite observed effectiveness');
select is((select priority::int from learning_goals where user_id='f0000000-0000-4000-8000-000000000001' and goal_type='work'),5,'goal priority saved');
select is((select strength::int from learning_preferences where user_id='f0000000-0000-4000-8000-000000000001' and target_key='conversation'),-2,'explicit rejection preserved');
select lives_ok($$select save_product_settings('f0000000-0000-4000-8000-000000000001',jsonb_set((select data from settings_payload),'{methods,conversation}','2'))$$,'learner can change their mind');
select is((select strength::int from learning_preferences where user_id='f0000000-0000-4000-8000-000000000001' and target_key='conversation'),2,'updated preference replaces rejection');
select is((select count(*)::int from learning_preferences where user_id='f0000000-0000-4000-8000-000000000002'),0,'other learner remains untouched');
select throws_ok($$select save_product_settings('f0000000-0000-4000-8000-000000000001',(select data||'{"entitlements":{"ads_enabled":false}}'::jsonb from settings_payload))$$,'P0001','Invalid settings','commercial access is not editable here');
select ok(not has_function_privilege('authenticated','public.save_product_settings(uuid,jsonb)','EXECUTE'),'ordinary clients cannot call settings service RPC directly');
select is((select count(*)::int from learner_model_changes where user_id='f0000000-0000-4000-8000-000000000001'),0,'no artificial learner-model changes');
select * from finish();
rollback;
